#!/usr/bin/env bash
# Shelter bridge: keep an offloaded service's state copyable from the NAS, and
# keep its ingest door where the humans already are.
#
# One JSON document describes both directions, generated by
# `modules/services/offload-bridge.nix`, so the unit and a hand run cannot
# disagree about where state goes:
#
#   bash offload-bridge.sh push      # /etc/offload-bridge/config.json
#   bash offload-bridge.sh ingest
#
# Two rules the code below exists to keep:
#
#  - The database is never copied file-by-file. Paperless and Vaultwarden both
#    run SQLite in WAL mode, and an rsync of a live `db.sqlite3` plus a stale
#    `-wal` is a torn database that restores into a service that starts and
#    then answers wrong. The tree is mirrored with the database excluded, and
#    the database is replaced by `sqlite3 .backup`, which is consistent by
#    construction.
#  - Every path is mirrored, not accumulated. The far side of a push is
#    `/srv/backup/offload/<set>/`, and the versioning that matters is frieren's
#    own restic snapshot at 03:30 — the same arrangement that carries
#    `/srv/backup/agent-turns`.
set -euo pipefail

CONFIG="${BRIDGE_CONFIG:-/etc/offload-bridge/config.json}"
cmd="${1:-}"

die() {
  echo "offload-bridge: $*" >&2
  exit 1
}

[ -n "$cmd" ] || die "usage: offload-bridge.sh push|ingest"
[ -n "${CONFIG}" ] || die "BRIDGE_CONFIG is not set"
[ -r "${CONFIG}" ] || die "cannot read ${CONFIG}"
for tool in jq rsync ssh sqlite3 find; do
  command -v "$tool" >/dev/null 2>&1 || die "missing tool: $tool"
done

SHELTER="$(jq -er '.shelter.host' "$CONFIG")"
ROOT="$(jq -er '.shelter.root' "$CONFIG")"
KEY="$(jq -er '.shelter.keyFile' "$CONFIG")"
KNOWN_HOSTS="$(jq -er '.shelter.knownHosts' "$CONFIG")"

# `accept-new` plus a state-file known_hosts: root's first contact with the
# shelter must not be an interactive prompt, and the pin has to survive the run
# that made it. `sudo rsync` on both ends because the service trees are 0700 to
# a service user and /srv/backup is root-owned.
mkdir -p "$(dirname "$KNOWN_HOSTS")"
SSH_OPTS=(-o BatchMode=yes -o ConnectTimeout=15 -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile="$KNOWN_HOSTS" -i "$KEY")
RSYNC_RSH="ssh ${SSH_OPTS[*]}"
rsync_to() { rsync -a "$@" --rsync-path="sudo rsync" -e "$RSYNC_RSH"; }

push() {
  local stage name path db rel
  stage="$(mktemp -d)"
  trap 'rm -rf "$stage"' RETURN

  ssh "${SSH_OPTS[@]}" "$SHELTER" "sudo install -d -m 0755 '$ROOT'"

  while IFS=$'\t' read -r name path; do
    echo "== push ${name}: ${path} -> ${SHELTER}:${ROOT}/${name}"
    install -d -m 0700 "$stage/$name"

    # Excludes are built from the set's own database list, so a `-wal`/`-shm`
    # file cannot ride along beside the consistent snapshot that replaces it.
    local excludes=()
    local dbs
    dbs="$(jq -r --arg n "$name" '.sets[$n].sqlite[]?' "$CONFIG")"
    while IFS= read -r db; do
      [ -n "$db" ] || continue
      excludes+=(--exclude "$db" --exclude "$db-wal" --exclude "$db-shm")
    done <<<"$dbs"

    rsync_to --delete --delay-updates "${excludes[@]}" "$path/" "$SHELTER:$ROOT/$name/"

    while IFS= read -r db; do
      [ -n "$db" ] || continue
      rel="$stage/$name/$(basename "$db")"
      sqlite3 "$path/$db" ".backup '$rel'"
      rsync_to "$rel" "$SHELTER:$ROOT/$name/$db"
      ssh "${SSH_OPTS[@]}" "$SHELTER" "sudo test -s '$ROOT/$name/$db'" ||
        die "shelter copy of ${name}/${db} is missing or empty after push"
      echo "   database ${db} -> $(du -h "$rel" | cut -f1) (consistent snapshot)"
    done <<<"$dbs"
  done < <(jq -r '.sets | to_entries[] | [.key, .value.path] | @tsv' "$CONFIG")
}

ingest() {
  local name from to owner
  local count
  count="$(jq -r '.ingest | length' "$CONFIG")"
  [ "$count" -gt 0 ] || {
    echo "offload-bridge: no ingest entries; nothing to pull"
    return 0
  }

  while IFS=$'\t' read -r name from to; do
    install -d -m 0750 "$to"
    owner="$(stat -c '%u:%g' "$to")"
    echo "== ingest ${name}: ${from} -> ${to}"
    # `--ignore-existing` is what makes a re-run harmless: a file already here
    # is skipped, and rsync only removes a source file it actually transferred.
    # The scanner still drops into the NAS share, so this is the door that keeps
    # working after the service moved hosts.
    rsync_to --ignore-existing --remove-source-files --chown="$owner" "$from" "$to"
  done < <(jq -r '.ingest | to_entries[] | [.key, .value.from, .value.to] | @tsv' "$CONFIG")
}

case "$cmd" in
  push) push ;;
  ingest) ingest ;;
  *) die "unknown command: $cmd (want push|ingest)" ;;
esac
